effect.frag.content:
int sourceIndex = 0;
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return imageAt(sourceIndex, uv);
}
void main() {
  vec2 p = v_uv - 0.5;
  float wave = sin(TAU * u_progress) * u_amount;
  vec2 uv = v_uv + vec2(sin(p.y * 9.0), sin(p.x * 7.0)) * wave * 0.12 * exp(-dot(p, p) * 4.0);
  if (inputCount == 1) fragColor = sourceAt(uv);
  else {
    float blend = 0.5 - 0.5 * cos(TAU * u_progress);
    vec2 reverseUv = v_uv - (uv - v_uv);
    vec4 first = sourceAt(uv);
    sourceIndex = 1;
    fragColor = mix(first, sourceAt(reverseUv), blend);
  }
}
